<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class AttendanceRecord extends Model{protected $fillable=['uuid','attendance_event_id','attendance_participant_id','status','checked_in_at','verification_method','verification_level','confirmed_at','acknowledged_at','consent_text_version','verification_code','evidence_hash','integrity_version','voided_at','voided_by','void_reason','manual_reason','created_by'];protected $casts=['checked_in_at'=>'datetime','confirmed_at'=>'datetime','acknowledged_at'=>'datetime','voided_at'=>'datetime'];public function event(){return$this->belongsTo(AttendanceEvent::class,'attendance_event_id');}public function participant(){return$this->belongsTo(AttendanceParticipant::class,'attendance_participant_id');}public function signature(){return$this->hasOne(AttendanceSignature::class);}}
